cases.bad:
// offsetController.ts — settingsStore already statically imported for saveSettings
import { saveSettings } from '@/shared/lib/storage/settingsStore';
// ...
// Dynamic import for loadSettings is pointless (module already in bundle)
const { loadSettings } = await import('@/shared/lib/storage/settingsStore');
// → Vite injects modulepreload-polyfill (uses document) into shared settingsStore chunk
// → SW imports same chunk → ReferenceError: document is not defined
// → SW registration failed (status 15) → content-script PAGE_SCAN_RESULT fails
// → "Receiving end does not exist" → popup detects no media

cases.good:
// Static import — module already in bundle, no code-split benefit lost
import { loadSettings, saveSettings } from '@/shared/lib/storage/settingsStore';
// ...
return loadSettings();
// SW bundle no longer references modulepreload; settingsStore chunk clean of polyfill
